/// The shared error-classification and retry rules (`spec/error-rules.json`).
///
/// The same JSON file drives every EchoNova SDK. Flutter apps can't read
/// package files at runtime, so the data is compiled into [errorRules]
/// (`rules.g.dart`, generated by `tools/gen_dart_rules.py`). This library
/// holds the types and answers "which rule matches this response?". Deciding
/// whether to retry is in `retry.dart`.
library;

part 'rules.g.dart';

/// Whether one column of the retry table allows a retry.
enum RetryFlag {
  /// Never retried.
  no,

  /// Retried while the retry budget lasts.
  yes,

  /// Retried at most once.
  once,

  /// Retried only when the caller opted in (`waitForSlot`).
  optIn;

  /// Parses the JSON value: `true`, `false`, `"once"` or `"opt_in"`.
  static RetryFlag fromJson(Object? value) => switch (value) {
        true => RetryFlag.yes,
        false => RetryFlag.no,
        'once' => RetryFlag.once,
        'opt_in' => RetryFlag.optIn,
        _ => throw FormatException('unknown retry flag: $value'),
      };
}

/// How long to wait before a retry.
enum RetryDelay {
  /// Not retried.
  none('none'),

  /// Exponential backoff with jitter.
  backoff('backoff'),

  /// The server's `Retry-After`, plus jitter. No retry without it.
  retryAfter('retry_after'),

  /// The server's `Retry-After` when present, otherwise backoff.
  retryAfterOrBackoff('retry_after_or_backoff');

  const RetryDelay(this.key);

  /// The value used in `error-rules.json`.
  final String key;

  /// Parses the JSON value.
  static RetryDelay fromJson(Object? value) => values.firstWhere(
        (delay) => delay.key == value,
        orElse: () => throw FormatException('unknown retry delay: $value'),
      );
}

/// Whether a failed POST may already have run (and been charged).
enum Executed {
  /// It definitely did not run.
  no,

  /// It may have run.
  yes,

  /// Unknown.
  unknown;

  /// Parses the JSON value: `"no"`, `"yes"` or `"unknown"`.
  static Executed fromJson(Object? value) => values.firstWhere(
        (executed) => executed.name == value,
        orElse: () =>
            throw FormatException('unknown may_have_executed: $value'),
      );
}

/// One row of the retry table: a flag per method, and the delay kind.
final class RetryColumns {
  /// Creates a row of the retry table.
  const RetryColumns({
    required this.get,
    required this.delete,
    required this.post,
    required this.postIdempotent,
    required this.ws,
    required this.delay,
  });

  /// Parses the `retry` object of a rule.
  factory RetryColumns.fromJson(Map<String, Object?> json) {
    const columns = ['GET', 'DELETE', 'POST', 'POST_IDEMPOTENT', 'WS', 'delay'];
    final missing = columns.where((c) => !json.containsKey(c)).toList();
    if (missing.isNotEmpty) {
      throw FormatException('retry columns missing $missing');
    }
    return RetryColumns(
      get: RetryFlag.fromJson(json['GET']),
      delete: RetryFlag.fromJson(json['DELETE']),
      post: RetryFlag.fromJson(json['POST']),
      postIdempotent: RetryFlag.fromJson(json['POST_IDEMPOTENT']),
      ws: RetryFlag.fromJson(json['WS']),
      delay: RetryDelay.fromJson(json['delay']),
    );
  }

  /// GET (and HEAD) requests.
  final RetryFlag get;

  /// DELETE requests.
  final RetryFlag delete;

  /// POST requests, and any other method.
  final RetryFlag post;

  /// A POST sent with an `Idempotency-Key`, to an operation that accepts
  /// one (ADR 0014): repeating it returns the first result, so it may be
  /// retried after it may have run.
  final RetryFlag postIdempotent;

  /// The WebSocket handshake.
  final RetryFlag ws;

  /// How long to wait before the retry.
  final RetryDelay delay;

  /// The flag for [method]. Methods other than GET, HEAD, DELETE and WS are
  /// treated as POST: not idempotent. A POST [withIdempotencyKey] uses
  /// [postIdempotent].
  RetryFlag forMethod(String method, {bool withIdempotencyKey = false}) {
    switch (method.toUpperCase()) {
      case 'GET' || 'HEAD':
        return get;
      case 'DELETE':
        return delete;
      case 'WS':
        return ws;
      case 'POST' when withIdempotencyKey:
        return postIdempotent;
      default:
        return post;
    }
  }
}

/// A rule that classifies an HTTP error status (REST or WebSocket handshake).
///
/// Every condition that is set must hold. Message conditions compare the
/// envelope's `errorMessage` after trimming whitespace.
final class ErrorRule {
  /// Creates a rule.
  const ErrorRule({
    required this.id,
    required this.row,
    required this.error,
    required this.retry,
    required this.mayHaveExecuted,
    this.statuses,
    this.statusRange,
    this.messageEquals,
    this.messagePrefix,
    this.messageSuffix,
    this.messageContains,
    this.json,
    this.retryAfter,
    this.blocksBucket = false,
    this.fromProxy = false,
  });

  /// Parses one entry of the `rules` array.
  factory ErrorRule.fromJson(Map<String, Object?> json) {
    final match = _map(json['match']);
    final status = match['status'];
    final bounds = match['status_range'];
    return ErrorRule(
      id: json['id']! as String,
      row: json['row']! as String,
      error: json['error']! as String,
      retry: RetryColumns.fromJson(_map(json['retry'])),
      mayHaveExecuted: Executed.fromJson(json['may_have_executed']),
      statuses: switch (status) {
        null => null,
        final List<Object?> list => {for (final s in list) s! as int},
        _ => {status as int},
      },
      statusRange: bounds is List<Object?>
          ? (bounds[0]! as int, bounds[1]! as int)
          : null,
      messageEquals: match['message_equals'] as String?,
      messagePrefix: match['message_prefix'] as String?,
      messageSuffix: match['message_suffix'] as String?,
      messageContains: match['message_contains'] as String?,
      json: match['json'] as bool?,
      retryAfter: match['retry_after'] as bool?,
      blocksBucket: json['blocks_bucket'] as bool? ?? false,
      fromProxy: json['from_proxy'] as bool? ?? false,
    );
  }

  /// A stable identifier, such as `throttled`.
  final String id;

  /// The row of the retry table (`R1`–`R18`).
  final String row;

  /// The error class, by its name in the shared taxonomy (`RateLimitError`).
  final String error;

  /// Whether, and how, each method is retried.
  final RetryColumns retry;

  /// Whether a POST that got this response may have run.
  final Executed mayHaveExecuted;

  /// The statuses this rule matches, or `null` for any.
  final Set<int>? statuses;

  /// An inclusive status range this rule matches, or `null` for any.
  final (int, int)? statusRange;

  /// The trimmed message must equal this.
  final String? messageEquals;

  /// The trimmed message must start with this.
  final String? messagePrefix;

  /// The trimmed message must end with this.
  final String? messageSuffix;

  /// The trimmed message must contain this.
  final String? messageContains;

  /// Whether the body must (true) or must not (false) be an EchoNova envelope.
  final bool? json;

  /// Whether a `Retry-After` header must (true) or must not (false) be present.
  final bool? retryAfter;

  /// A throttle: callers on the same endpoint wait out `Retry-After`.
  final bool blocksBucket;

  /// The response came from the hosting proxy, not from the API.
  final bool fromProxy;

  /// Whether this rule matches a response.
  bool matches(
    int status, {
    required bool isJson,
    required String? message,
    required bool hasRetryAfter,
  }) {
    final statuses = this.statuses;
    if (statuses != null && !statuses.contains(status)) return false;
    final range = statusRange;
    if (range != null && (status < range.$1 || status > range.$2)) {
      return false;
    }
    if (json != null && json != isJson) return false;
    if (retryAfter != null && retryAfter != hasRetryAfter) return false;
    final text = message?.trim();
    bool check(String? expected, bool Function(String text, String v) test) =>
        expected == null || (text != null && test(text, expected));
    return check(messageEquals, (t, v) => t == v) &&
        check(messagePrefix, (t, v) => t.startsWith(v)) &&
        check(messageSuffix, (t, v) => t.endsWith(v)) &&
        check(messageContains, (t, v) => t.contains(v));
  }
}

/// A failure without an HTTP status (connect error, timeout, broken body).
final class TransportRule {
  /// Creates a transport rule.
  const TransportRule({
    required this.row,
    required this.phase,
    required this.error,
    required this.retry,
    required this.mayHaveExecuted,
  });

  /// Parses one entry of the `transport` array.
  factory TransportRule.fromJson(Map<String, Object?> json) => TransportRule(
        row: json['row']! as String,
        phase: json['phase']! as String,
        error: json['error']! as String,
        retry: RetryColumns.fromJson(_map(json['retry'])),
        mayHaveExecuted: Executed.fromJson(json['may_have_executed']),
      );

  /// The row of the retry table (`R1`–`R4`).
  final String row;

  /// The failure phase, such as `no_response`.
  final String phase;

  /// The error class, by its name in the shared taxonomy.
  final String error;

  /// Whether, and how, each method is retried.
  final RetryColumns retry;

  /// Whether a POST that failed this way may have run.
  final Executed mayHaveExecuted;
}

/// Retry defaults shared by every SDK. Times are in seconds, as in the JSON.
final class RetryDefaults {
  /// Creates the defaults.
  const RetryDefaults({
    required this.maxRetries,
    required this.backoffInitialSeconds,
    required this.backoffMultiplier,
    required this.backoffMaxSeconds,
    required this.backoffJitter,
    required this.retryAfterJitterSeconds,
    required this.maxRetryAfterSeconds,
    required this.wsMaxRetryAfterSeconds,
  });

  /// Parses the `defaults` object.
  factory RetryDefaults.fromJson(Map<String, Object?> json) {
    final backoff = _map(json['backoff']);
    final jitter = _numbers(backoff['jitter']);
    final retryAfterJitter = _numbers(json['retry_after_jitter_seconds']);
    return RetryDefaults(
      maxRetries: json['max_retries']! as int,
      backoffInitialSeconds: _number(backoff['initial_seconds']),
      backoffMultiplier: _number(backoff['multiplier']),
      backoffMaxSeconds: _number(backoff['max_seconds']),
      backoffJitter: (jitter[0], jitter[1]),
      retryAfterJitterSeconds: (retryAfterJitter[0], retryAfterJitter[1]),
      maxRetryAfterSeconds: _number(json['max_retry_after_seconds']),
      wsMaxRetryAfterSeconds:
          _number(json['ws_handshake_max_retry_after_seconds']),
    );
  }

  /// Retries per request (429 retries count too).
  final int maxRetries;

  /// The first backoff delay.
  final double backoffInitialSeconds;

  /// The backoff growth factor.
  final double backoffMultiplier;

  /// The largest backoff delay.
  final double backoffMaxSeconds;

  /// The backoff is multiplied by a random factor in this range.
  final (double, double) backoffJitter;

  /// A random delay in this range is added to `Retry-After`.
  final (double, double) retryAfterJitterSeconds;

  /// A longer REST `Retry-After` is not waited for.
  final double maxRetryAfterSeconds;

  /// A longer WebSocket-handshake `Retry-After` is not waited for.
  final double wsMaxRetryAfterSeconds;
}

/// The complete rule set: taxonomy, ordered rules, transport rows, defaults.
final class RuleSet {
  /// Creates a rule set.
  const RuleSet({
    required this.version,
    required this.taxonomy,
    required this.rules,
    required this.transport,
    required this.defaults,
  });

  /// Parses `error-rules.json`. The SDK uses the compiled [errorRules]; this
  /// is for tests and tools.
  factory RuleSet.fromJson(Map<String, Object?> json) => RuleSet(
        version: json['version']! as int,
        taxonomy: {
          for (final MapEntry(:key, :value) in _map(json['taxonomy']).entries)
            key: value as String?,
        },
        rules: [
          for (final rule in json['rules']! as List<Object?>)
            ErrorRule.fromJson(_map(rule)),
        ],
        transport: {
          for (final row in json['transport']! as List<Object?>)
            _map(row)['phase']! as String: TransportRule.fromJson(_map(row)),
        },
        defaults: RetryDefaults.fromJson(_map(json['defaults'])),
      );

  /// The rules format version.
  final int version;

  /// Error class name to parent class name (`null` for the root).
  final Map<String, String?> taxonomy;

  /// Classification rules, in order. The first match wins.
  final List<ErrorRule> rules;

  /// Failures without an HTTP status, by phase.
  final Map<String, TransportRule> transport;

  /// Retry defaults.
  final RetryDefaults defaults;

  /// The first rule that matches. The rules end with catch-alls, so every
  /// 4xx and 5xx status matches; other statuses throw [StateError].
  ErrorRule classify(
    int status, {
    required bool isJson,
    required String? message,
    required bool hasRetryAfter,
  }) {
    for (final rule in rules) {
      if (rule.matches(
        status,
        isJson: isJson,
        message: message,
        hasRetryAfter: hasRetryAfter,
      )) {
        return rule;
      }
    }
    throw StateError('no error rule matches status $status');
  }

  /// The rule with [id], or `null`.
  ErrorRule? ruleById(String id) {
    for (final rule in rules) {
      if (rule.id == id) return rule;
    }
    return null;
  }
}

Map<String, Object?> _map(Object? value) => (value! as Map).cast();

double _number(Object? value) => (value! as num).toDouble();

List<double> _numbers(Object? value) =>
    [for (final item in value! as List<Object?>) _number(item)];
